bool FileDeltas::validJsonOfField(
    size_t index, const std::string& fieldName, const Json::Value& pJson, std::string& err, bool isForCreation) {
    switch (index) {

        case 0:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (isForCreation) {
                err = "The automatic primary key cannot be set";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 1:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 2:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 3:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 4:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 5:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isString()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            if (pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 88) {
                err = "String length exceeds limit for the " + fieldName + " field (the maximum value is 88)";
                return false;
            }

            break;

        case 6:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isString()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 7:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isInt64()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        case 8:

            if (pJson.isNull()) {
                err = "The " + fieldName + " column cannot be null";
                return false;
            }

            if (!pJson.isString()) {
                err = "Type error in the " + fieldName + " field";
                return false;
            }

            break;

        default:
            err = "Internal error in the server";
            return false;
    }
    return true;
}
